class DataProvider with ChangeNotifier {
  bool _isLoading = false;
  String? _data;
  String? _error;

  bool get isLoading => _isLoading;
  String? get data => _data;
  String? get error => _error;

  Future<void> fetchData() async {
    _isLoading = true;
    _error = null;
    notifyListeners();

    try {
      // Simulate API call
      await Future.delayed(Duration(seconds: 2));
      _data = "Fetched Data";
    } catch (e) {
      _error = e.toString();
    } finally {
      _isLoading = false;
      notifyListeners();
    }
  }
}

